var builder = WebApplication.CreateBuilder(args);
builder.Services.AddAuthentication().AddCookie(); // SameSite=Lax
builder.Services.AddAuthorization();
builder.Services.AddSingleton<UserStore>();
var app = builder.Build();
app.UseAuthentication();
app.UseAuthorization();

// "Only our settings page links here, and it carries the cookie"
app.MapGet("/settings/2fa/disable", async (
    ClaimsPrincipal user, UserStore users) =>
{
    await users.DisableTwoFactorAsync(user.Identity!.Name!);
    return Results.Redirect("/settings");
}).RequireAuthorization();
app.Run();

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddAuthentication().AddCookie(o =>
    o.Cookie.SameSite = SameSiteMode.Strict); // extra layer, not the fix
builder.Services.AddAuthorization();
builder.Services.AddAntiforgery();
builder.Services.AddSingleton<UserStore>();
var app = builder.Build();
app.UseAuthentication();
app.UseAuthorization();
app.UseAntiforgery(); // after authentication and authorization

app.MapGet("/settings", (HttpContext ctx, IAntiforgery antiforgery) =>
{
    var tokens = antiforgery.GetAndStoreTokens(ctx); // a hidden field
    return Results.Content(SettingsPage.Render(tokens), "text/html");
}).RequireAuthorization();

// POST only, and the form must carry the token and the password
app.MapPost("/settings/2fa/disable", async ([FromForm] string password,
    ClaimsPrincipal user, UserStore users) =>
    await users.DisableTwoFactorAsync(user.Identity!.Name!, password)
        ? Results.Redirect("/settings") : Results.BadRequest())
    .RequireAuthorization();
app.Run();
